//! Task T-6: the first complete read (`Dump::read_table`, `TableBatches`, the builders, the file-order to
//! declared-order placement).
//!
//! Expected values come from the plan (T-6 "Done when"), the truth files of `corpus/fixtures/{18c,11g}`, the SQL
//! of `corpus/sql/11_types.sql` / `14_long2.sql` (value texts), `tests/golden/exp_raw.tsv` (generated by
//! `tests/golden/gen_exp_raw.py` from the Analyst's `docs/formats/tools/exp_parse.py`: per part the SHA-256 of
//! the raw fields and, per LONG column, of the assembled values) and `tests/data/value_parts.tsv` (the Analyst's
//! `exp_parse.py` through `gen_number_parts.py`).
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::panic
)]

mod common;

use arrow_array::cast::AsArray;
use arrow_array::types::{Decimal128Type, Int64Type, TimestampSecondType};
use arrow_array::{Array, RecordBatch};
use arrow_schema::{DataType, TimeUnit};
use common::*;
use oradmp_core::dump::{open, Options};
use oradmp_core::reader::{OnValueError, ReadOptions};
use oradmp_core::types::map::NumberType;
use oradmp_core::values::number::OverflowPolicy;
use oradmp_core::{ErrorCode, WarningCode};
use sha2::{Digest, Sha256};

const VERSIONS: [(&str, &str); 2] = [("18c", "18c"), ("11g", "11g")];

fn opts() -> ReadOptions {
    ReadOptions::default()
}

fn col(batches: &[RecordBatch], c: usize) -> Vec<String> {
    rows(batches).into_iter().map(|r| r[c].clone()).collect()
}

fn data_equal(a: &[RecordBatch], b: &[RecordBatch]) {
    assert_eq!(a.len(), b.len(), "number of batches");
    for (x, y) in a.iter().zip(b) {
        assert_eq!(x.num_columns(), y.num_columns());
        for (cx, cy) in x.columns().iter().zip(y.columns()) {
            assert_eq!(cx.to_data(), cy.to_data());
        }
    }
}

/// (a) `truth_stat.txt` `ROW|` lines (50) = T_STAT1 of `stat_exp_<v>.dmp`, both versions; ID Int64, V Utf8,
/// N Decimal128(38,10) (a plain NUMBER), D Timestamp(Second).
#[test]
fn t_stat1_equals_the_50_truth_rows_in_both_versions() {
    for (folder, v) in VERSIONS {
        let (b, w) = read_default(&format!("{folder}/stat_exp_{v}.dmp"), "T_STAT1");
        assert!(w.is_empty(), "{folder}: {w:?}");
        let schema = b[0].schema();
        let types: Vec<_> = schema
            .fields()
            .iter()
            .map(|f| f.data_type().clone())
            .collect();
        assert_eq!(
            types,
            [
                DataType::Int64,
                DataType::Utf8,
                DataType::Decimal128(38, 10),
                DataType::Timestamp(TimeUnit::Second, None)
            ]
        );
        let names: Vec<_> = schema.fields().iter().map(|f| f.name().clone()).collect();
        assert_eq!(names, ["ID", "V", "N", "D"]);
        let truth_rows: Vec<Vec<String>> = truth(folder, "truth_stat.txt")
            .into_iter()
            .filter(|l| l[0] == "ROW")
            .map(|l| l[1..].to_vec())
            .collect();
        assert_eq!(truth_rows.len(), 50);
        let got: Vec<Vec<String>> = rows(&b)
            .into_iter()
            .map(|mut r| {
                // D: the truth prints the date only; the time is midnight
                assert!(r[3].ends_with(" 00:00:00"), "{r:?}");
                r[3].truncate(10);
                r
            })
            .collect();
        assert_eq!(got, truth_rows, "{folder}");
    }
}

fn manifest(file: &str, table: &str) -> Vec<Vec<String>> {
    let text = std::fs::read_to_string(root().join("tests/golden/exp_raw.tsv")).unwrap();
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.starts_with("file\t"))
        .map(|l| l.split('\t').map(str::to_string).collect::<Vec<_>>())
        .filter(|c| c[0] == file && c[3] == table)
        .collect()
}

/// The raw serialisation of `exp_raw.tsv` for a field list: NULL = ff ff ff ff, else u32 LE length + bytes.
fn feed(h: &mut Sha256, field: Option<&[u8]>) {
    match field {
        None => h.update([0xff; 4]),
        Some(b) => {
            h.update((b.len() as u32).to_le_bytes());
            h.update(b);
        }
    }
}

/// (b) R_STAT of `ru_stat_exp_cp1251_est_11g.dmp`: 2000 rows; the fields re-encoded from the Arrow values
/// (NUMBER by a test-only encoder, text by CL8MSWIN1251, DATE by the 7-byte layout) reproduce the SHA-256 of
/// the raw manifest (`exp_raw.tsv`, from the Analyst's `exp_parse.py`).
#[test]
fn r_stat_reencoded_fields_reproduce_the_manifest_hash() {
    let file = "11g-cp1251/ru_stat_exp_cp1251_est_11g.dmp";
    let (batches, w) = read_default(file, "R_STAT");
    assert!(w.is_empty(), "{w:?}");
    assert_eq!(row_count(&batches), 2000);
    let m = manifest(file, "R_STAT");
    assert_eq!(m.len(), 1);
    assert_eq!(m[0][9], "2000");
    let mut h = Sha256::new();
    for b in &batches {
        for i in 0..b.num_rows() {
            for c in b.columns() {
                if c.is_null(i) {
                    feed(&mut h, None);
                    continue;
                }
                let bytes: Vec<u8> = match c.data_type() {
                    DataType::Int64 => {
                        encode_number(i128::from(c.as_primitive::<Int64Type>().value(i)), 0)
                    }
                    DataType::Decimal128(_, s) => encode_number(
                        c.as_primitive::<Decimal128Type>().value(i),
                        u32::from(*s as u8),
                    ),
                    DataType::Utf8 => {
                        let (enc, _, bad) =
                            encoding_rs::WINDOWS_1251.encode(c.as_string::<i32>().value(i));
                        assert!(!bad);
                        enc.into_owned()
                    }
                    DataType::Timestamp(TimeUnit::Second, _) => {
                        encode_date(c.as_primitive::<TimestampSecondType>().value(i))
                    }
                    t => panic!("{t:?}"),
                };
                feed(&mut h, Some(&bytes));
            }
        }
    }
    assert_eq!(hex(&h.finalize()), m[0][11]);
}

/// R_STAT: the types of the declared columns (architecture 5.1) and a Cyrillic value decoded from cp1251.
#[test]
fn r_stat_types_and_cyrillic_text() {
    let (b, _) = read_default("11g-cp1251/ru_stat_exp_cp1251_est_11g.dmp", "R_STAT");
    let types: Vec<_> = b[0]
        .schema()
        .fields()
        .iter()
        .map(|f| f.data_type().clone())
        .collect();
    assert_eq!(
        types,
        [
            DataType::Int64,
            DataType::Int64,
            DataType::Utf8,
            DataType::Utf8,
            DataType::Timestamp(TimeUnit::Second, None),
            DataType::Decimal128(10, 2),
            DataType::Utf8
        ]
    );
    // the same table of the AL32UTF8 database of `ru_stat_exp_al32utf8_est_11g.dmp` has the same text
    let (u, _) = read_default("11g-cp1251/ru_stat_exp_al32utf8_est_11g.dmp", "R_STAT");
    assert_eq!(col(&b, 2), col(&u, 2));
    assert!(col(&b, 2)
        .iter()
        .any(|t| t.chars().any(|c| ('\u{400}'..='\u{4ff}').contains(&c))));
}

/// (c) batches respect both limits: `batch_rows` 1, 7 and 65,536 on the 2000 rows of R_STAT; the rows are the
/// same whatever the limit; `batch_bytes` closes a batch after the row that reaches it.
#[test]
fn batches_respect_batch_rows_and_batch_bytes() {
    let file = "11g-cp1251/ru_stat_exp_cp1251_est_11g.dmp";
    let mut d = open_fixture(file);
    let (all, _) = read(&mut d, "R_STAT", &opts());
    assert_eq!(all.len(), 1);
    let expected = rows(&all);
    for (limit, count) in [(1usize, 2000usize), (7, 286), (65_536, 1)] {
        let (b, _) = read(
            &mut d,
            "R_STAT",
            &ReadOptions {
                batch_rows: limit,
                ..opts()
            },
        );
        assert_eq!(b.len(), count, "batch_rows {limit}");
        assert!(b.iter().all(|x| x.num_rows() <= limit));
        assert_eq!(rows(&b), expected, "batch_rows {limit}");
    }
    // bytes: ID, GRP, AMT, DT are 8 + 8 + 16 + 8 = 40 fixed bytes; TXT, CODE, NOTE add their UTF-8 bytes
    let first_row_bytes: usize = {
        let r = &expected[0];
        40 + r[2].len() + r[3].len() + r[6].len()
    };
    let cap = first_row_bytes as u64;
    let (b, _) = read(
        &mut d,
        "R_STAT",
        &ReadOptions {
            batch_bytes: cap,
            ..opts()
        },
    );
    assert!(b.len() > 1);
    assert_eq!(
        b[0].num_rows(),
        1,
        "the batch closes after the row that reaches the cap"
    );
    assert_eq!(rows(&b), expected);
    let (b, _) = read(
        &mut d,
        "R_STAT",
        &ReadOptions {
            batch_bytes: 1,
            ..opts()
        },
    );
    assert_eq!(b.len(), 2000);
}

/// (d) `stat_exp_none`, `stat_exp_compute`, `stat_exp_us7ascii` (and the direct-path export) give the same
/// data as `stat_exp` (statistics items change nothing, S6, S7), in all four tables, both versions.
#[test]
fn statistics_variants_give_the_same_batches() {
    for (folder, v) in VERSIONS {
        let mut base = open_fixture(&format!("{folder}/stat_exp_{v}.dmp"));
        let names: Vec<String> = base
            .tables()
            .unwrap()
            .iter()
            .map(|t| t.name.clone())
            .collect();
        assert_eq!(names, ["T_STAT1", "T_STAT2", "T_STAT3", "T_STAT4"]);
        for variant in ["none", "compute", "us7ascii", "direct"] {
            let mut other = open_fixture(&format!("{folder}/stat_exp_{variant}_{v}.dmp"));
            for t in &names {
                let (a, _) = read(&mut base, t, &opts());
                let (b, w) = read(&mut other, t, &opts());
                assert!(w.is_empty(), "{variant} {t}: {w:?}");
                data_equal(&a, &b);
            }
        }
        // 50 rows in T_STAT1..3, none in T_STAT4
        let (b, _) = read(&mut base, "T_STAT4", &opts());
        assert_eq!(row_count(&b), 0);
    }
}

fn long_values(folder: &str, v: &str, kind: &str) -> (Vec<RecordBatch>, Vec<RecordBatch>) {
    let rel = format!("{folder}/{kind}_{v}.dmp");
    let mut d = open_fixture(&rel);
    (
        read(&mut d, "T_LONG", &opts()).0,
        read(&mut d, "T_LONGRAW", &opts()).0,
    )
}

/// Session 2/4: T_LONG and T_LONGRAW of `long_exp_<v>` are LargeUtf8 / LargeBinary with the values of
/// `corpus/sql/11_types.sql` (`short`, NULL, `L` + 31,999 x `x`; `00ff`, 32,000 x `ab`); the direct-path export
/// (chains of 5 pieces) gives the same values; declared column order (ID, L, V) although the direct file
/// stands ID, V, L (ADR-24); the assembled values reproduce the digests of the raw manifest.
#[test]
fn long_and_long_raw_values_conventional_and_direct() {
    for (folder, v) in VERSIONS {
        let mut expected_l = vec![
            "short".to_string(),
            "<NULL>".to_string(),
            format!("L{}", "x".repeat(31_999)),
        ];
        let (conv_l, conv_r) = long_values(folder, v, "long_exp");
        let (dir_l, dir_r) = long_values(folder, v, "long_exp_direct");
        for (l, r) in [(&conv_l, &conv_r), (&dir_l, &dir_r)] {
            assert_eq!(l[0].schema().field(1).data_type(), &DataType::LargeUtf8);
            assert_eq!(r[0].schema().field(1).data_type(), &DataType::LargeBinary);
            let names: Vec<_> = l[0]
                .schema()
                .fields()
                .iter()
                .map(|f| f.name().clone())
                .collect();
            assert_eq!(names, ["ID", "L", "V"], "declared order");
            assert_eq!(col(l, 1), expected_l);
            assert_eq!(col(l, 2), ["a", "b", "c"]);
            assert_eq!(col(l, 0), ["1", "2", "3"]);
            assert_eq!(col(r, 1), ["00ff".to_string(), "ab".repeat(32_000)]);
        }
        data_equal(&conv_l, &dir_l);
        data_equal(&conv_r, &dir_r);
        expected_l.clear();

        // the assembled-value digest of the manifest: NULL = 8 x ff, else the total as u64 LE and the bytes
        for (file, table, batches) in [
            (format!("{folder}/long_exp_{v}.dmp"), "T_LONG", &conv_l),
            (
                format!("{folder}/long_exp_direct_{v}.dmp"),
                "T_LONG",
                &dir_l,
            ),
            (format!("{folder}/long_exp_{v}.dmp"), "T_LONGRAW", &conv_r),
            (
                format!("{folder}/long_exp_direct_{v}.dmp"),
                "T_LONGRAW",
                &dir_r,
            ),
        ] {
            let m = manifest(&file, table);
            let digest = m[0][15].split(':').nth(2).unwrap().to_string();
            let mut h = Sha256::new();
            let a = batches[0].column(1);
            for i in 0..a.len() {
                if a.is_null(i) {
                    h.update([0xff; 8]);
                } else {
                    let bytes: Vec<u8> = match a.data_type() {
                        DataType::LargeUtf8 => a.as_string::<i64>().value(i).as_bytes().to_vec(),
                        _ => a.as_binary::<i64>().value(i).to_vec(),
                    };
                    h.update((bytes.len() as u64).to_le_bytes());
                    h.update(&bytes);
                }
            }
            assert_eq!(hex(&h.finalize()), digest, "{file} {table}");
        }
    }
}

/// `batch_bytes` with a LONG value: the 32,000-byte value stays whole; the batch closes after the row that
/// reaches the cap. T_LONG rows add 8 + 5 + 1 = 14, 8 + 0 + 1 = 9 and 8 + 32,000 + 1 = 32,009 bytes.
/// (The plan says "16 KiB forces one row per batch": by the rule of architecture 5.6 step 8 rows 1 and 2 stay
/// in the batch of row 3, which is what this test records; see `implementer-notes.md` N-18.)
#[test]
fn batch_bytes_with_a_long_value_never_splits_it() {
    let mut d = open_fixture("18c/long_exp_18c.dmp");
    let (b, _) = read(
        &mut d,
        "T_LONG",
        &ReadOptions {
            batch_bytes: 16 * 1024,
            ..opts()
        },
    );
    assert_eq!(b.len(), 1);
    assert_eq!(col(&b, 1)[2].len(), 32_000);
    let (b, _) = read(
        &mut d,
        "T_LONG",
        &ReadOptions {
            batch_bytes: 14,
            ..opts()
        },
    );
    assert_eq!(
        b.iter().map(RecordBatch::num_rows).collect::<Vec<_>>(),
        [1, 2]
    );
    let (b, _) = read(
        &mut d,
        "T_LONG",
        &ReadOptions {
            batch_bytes: 1,
            ..opts()
        },
    );
    assert_eq!(
        b.iter().map(RecordBatch::num_rows).collect::<Vec<_>>(),
        [1, 1, 1]
    );
    assert_eq!(col(&b, 1)[2].len(), 32_000);
}

/// Session 4: T_LONG2 row 1 decodes to `дж Café` from `long2_exp_<v>`, `long2_exp_us7ascii_<v>` (the database
/// set is AL32UTF8 in the header) and `long2_exp_direct_<v>`, with no warning. `truth_long2.txt` line 1:
/// `1|10|D0B4D0B620436166C3A9` (10 bytes of UTF-8).
#[test]
fn t_long2_decodes_cyrillic_and_accents_without_a_warning() {
    // T-10b: the truth comparison is a function of `common/truth_checks.rs` (also called by t10_truth.rs)
    let diffs = common::truth_checks::long2_diffs();
    assert!(diffs.is_empty(), "{diffs:?}");
    for (folder, v) in VERSIONS {
        for kind in ["long2_exp", "long2_exp_us7ascii", "long2_exp_direct"] {
            let (b, w) = read_default(&format!("{folder}/{kind}_{v}.dmp"), "T_LONG2");
            assert!(w.is_empty(), "{kind}: {w:?}");
            assert_eq!(col(&b, 1), ["\u{434}\u{436} Caf\u{e9}"], "{folder} {kind}");
            assert_eq!(
                hex(col(&b, 1)[0].as_bytes()).to_uppercase(),
                "D0B4D0B620436166C3A9"
            );
        }
    }
}

/// `max_lob_bytes` 20,000 gives `E-LOB-TOO-LARGE` on the 32,000-byte chain of `long_exp_direct` (column 3 in
/// the file order, row 3, part 1, with the offset); with `on_value_error="null"` the value is NULL with one
/// `W-VALUE-NULLED`, the other columns of the row and the next table are intact.
#[test]
fn max_lob_bytes_stops_a_long_chain_or_nulls_it() {
    let mut d = open_fixture("18c/long_exp_direct_18c.dmp");
    let e = try_read(
        &mut d,
        "T_LONG",
        &ReadOptions {
            max_lob_bytes: 20_000,
            ..opts()
        },
    )
    .unwrap_err();
    assert_eq!(e.code, ErrorCode::LobTooLarge);
    assert_eq!((e.row, e.part, e.column), (Some(3), Some(1), Some(3)));
    assert!(e.offset.is_some() && e.table == Some(1));
    assert!(e.length.unwrap() > 20_000);
    let o = ReadOptions {
        max_lob_bytes: 20_000,
        on_value_error: OnValueError::Null,
        ..opts()
    };
    let (b, w) = read(&mut d, "T_LONG", &o);
    assert_eq!(col(&b, 1), ["short", "<NULL>", "<NULL>"]);
    assert_eq!(col(&b, 2), ["a", "b", "c"]);
    let w: Vec<_> = w
        .iter()
        .filter(|w| w.code == WarningCode::ValueNulled)
        .collect();
    assert_eq!(w.len(), 1);
    assert_eq!(
        (w[0].count, w[0].row, w[0].column, w[0].part),
        (Some(1), Some(3), Some(3), Some(1))
    );
    let (f, _) = read(&mut d, "T_FRAME", &o);
    assert_eq!(row_count(&f), 7);
    // LONG RAW as well
    let e = try_read(
        &mut d,
        "T_LONGRAW",
        &ReadOptions {
            max_lob_bytes: 20_000,
            ..opts()
        },
    )
    .unwrap_err();
    assert_eq!(e.code, ErrorCode::LobTooLarge);
}

/// ADR-24: the schema follows the `CREATE TABLE` order, the decoder the file order. In `long_exp_direct` the
/// LONG column stands last in the file (ID, V, L) and second in the schema (ID, L, V); `T_LONG_EMPTY` (a
/// table without rows on the direct path) gives an empty batch list and the right schema.
#[test]
fn file_order_is_placed_in_declared_order() {
    let mut d = open_fixture("18c/long_exp_direct_18c.dmp");
    let t = d
        .table(oradmp_core::dump::TableRef::ByName("T_LONG"))
        .unwrap()
        .clone();
    let file: Vec<_> = {
        let mut c: Vec<_> = t
            .columns
            .iter()
            .map(|c| (c.file_position, c.name.clone()))
            .collect();
        c.sort();
        c.into_iter().map(|c| c.1).collect()
    };
    assert_eq!(file, ["ID", "V", "L"]);
    let (b, _) = read(&mut d, "T_LONG", &opts());
    assert_eq!(
        b[0].schema()
            .fields()
            .iter()
            .map(|f| f.name().as_str())
            .collect::<Vec<_>>(),
        ["ID", "L", "V"]
    );
    assert_eq!(rows(&b)[0], ["1", "short", "a"]);
    let (e, _) = read(&mut d, "T_LONG_EMPTY", &opts());
    assert_eq!(row_count(&e), 0);
}

/// `columns` keeps the table order, skips the rest by length, and a name that is not there is an error.
#[test]
fn column_selection_keeps_table_order() {
    let mut d = open_fixture("18c/stat_exp_18c.dmp");
    let (b, _) = read(
        &mut d,
        "T_STAT1",
        &ReadOptions {
            columns: Some(vec!["D".into(), "ID".into()]),
            ..opts()
        },
    );
    assert_eq!(
        b[0].schema()
            .fields()
            .iter()
            .map(|f| f.name().as_str())
            .collect::<Vec<_>>(),
        ["ID", "D"]
    );
    assert_eq!(row_count(&b), 50);
    let e = try_read(
        &mut d,
        "T_STAT1",
        &ReadOptions {
            columns: Some(vec!["NOPE".into()]),
            ..opts()
        },
    )
    .unwrap_err();
    assert_eq!(e.code, ErrorCode::NoSuchColumn);
}

/// T_INTERVAL (Interval(MonthDayNano) months, Duration(Microsecond)) and T_ROWID of `misc_exp_<v>` end to end
/// = `truth_misc.txt`: `INTERVAL|id|+0002-06|dump|+0010 12:30:45.123456|dump`, `ROWID|id|text|dump|text|dump`.
#[test]
fn intervals_and_rowids_equal_truth_misc() {
    // T-10b: the truth comparison is a function of `common/truth_checks.rs` (also called by t10_truth.rs)
    let diffs = common::truth_checks::misc_diffs();
    assert!(diffs.is_empty(), "{diffs:?}");
    for (folder, v) in VERSIONS {
        let t = truth(folder, "truth_misc.txt");
        let (b, w) = read_default(&format!("{folder}/misc_exp_{v}.dmp"), "T_INTERVAL");
        assert!(w.is_empty());
        let got = rows(&b);
        let lines: Vec<_> = t.iter().filter(|l| l[0] == "INTERVAL").collect();
        assert_eq!(got.len(), lines.len());
        for (g, l) in got.iter().zip(&lines) {
            assert_eq!(g[0], l[1]);
            if l[2] == "NULL" {
                assert_eq!((g[1].as_str(), g[2].as_str()), ("<NULL>", "<NULL>"));
                continue;
            }
            // +0002-06 -> months
            let sign = if l[2].starts_with('-') { -1 } else { 1 };
            let (y, m) = l[2][1..].split_once('-').unwrap();
            let months = sign * (y.parse::<i64>().unwrap() * 12 + m.parse::<i64>().unwrap());
            assert_eq!(g[1], format!("{months}m0d0ns"), "{folder} id {}", l[1]);
            // +0010 12:30:45.123456 -> microseconds
            let sign = if l[4].starts_with('-') { -1 } else { 1 };
            let (days, rest) = l[4][1..].split_once(' ').unwrap();
            let (hms, frac) = rest.split_once('.').unwrap();
            let p: Vec<i64> = hms.split(':').map(|x| x.parse().unwrap()).collect();
            let micros = sign
                * ((((days.parse::<i64>().unwrap() * 24 + p[0]) * 60 + p[1]) * 60 + p[2])
                    * 1_000_000
                    + frac.parse::<i64>().unwrap());
            assert_eq!(g[2], micros.to_string(), "{folder} id {}", l[1]);
        }
        let (b, w) = read_default(&format!("{folder}/misc_exp_{v}.dmp"), "T_ROWID");
        assert!(w.is_empty());
        let got = rows(&b);
        let lines: Vec<_> = t.iter().filter(|l| l[0] == "ROWID").collect();
        assert_eq!(got.len(), lines.len());
        for (g, l) in got.iter().zip(&lines) {
            let want = |s: &str| {
                if s == "NULL" {
                    "<NULL>".to_string()
                } else {
                    s.to_string()
                }
            };
            // the UROWID of the row is the ROWID of the same row (rule Y11, architecture 5.7 item 4): the truth
            // line holds its text only as the DUMP of the 13 bytes, so the text of column 2 stands for both
            assert_eq!(
                (g[0].clone(), g[1].clone(), g[2].clone()),
                (l[1].clone(), want(&l[2]), want(&l[2]))
            );
        }
    }
}

/// `misc2` (precisions 9): T_INTERVAL2 rows 2 and 3 have an INTERVAL YEAR(9) beyond 32-bit months
/// (`E-BAD-INTERVAL`, ADR-28 (a)); with `on_value_error="null"` they are NULL with one `W-VALUE-NULLED` of
/// count 2, and the INTERVAL DAY(9) TO SECOND(9) column (Interval(MonthDayNano)) equals `truth_misc2.txt`
/// (days, nanoseconds of the day). The logical UROWID of T_ROWID2 row 10 is `*BAMAFbMCwQL+`.
#[test]
fn misc2_intervals_and_the_logical_urowid() {
    let mut d = open_fixture("18c/misc2_exp_18c.dmp");
    let e = try_read(&mut d, "T_INTERVAL2", &opts()).unwrap_err();
    assert_eq!(e.code, ErrorCode::BadInterval);
    assert_eq!((e.row, e.column, e.part), (Some(2), Some(2), Some(1)));
    let (b, w) = read(
        &mut d,
        "T_INTERVAL2",
        &ReadOptions {
            on_value_error: OnValueError::Null,
            ..opts()
        },
    );
    let r = rows(&b);
    assert_eq!(r[1][1], "<NULL>");
    assert_eq!(r[2][1], "<NULL>");
    // row 1: -1 year 11 months = -23 months
    assert_eq!(r[0][1], "-13m0d0ns".replace("-13", "-23"));
    // row 1 IDS: -000000001 02:03:04.500000000 = days -1, nanoseconds -(2*3600 + 3*60 + 4.5) * 1e9
    assert_eq!(r[0][2], "0m-1d-7384500000000ns");
    assert_eq!(r[1][2], "0m999999999d86399999999999ns");
    assert_eq!(r[2][2], "0m-999999999d-86399999999999ns");
    // IDS0 INTERVAL DAY(2) TO SECOND(0): Duration(Microsecond): -00 00:00:01 = -1,000,000 us
    assert_eq!(r[0][3], "-1000000");
    let nulled: Vec<_> = w
        .iter()
        .filter(|w| w.code == WarningCode::ValueNulled)
        .collect();
    assert_eq!(nulled.len(), 1);
    assert_eq!(nulled[0].count, Some(2));
    let (b, _) = read_default("18c/misc2_exp_18c.dmp", "T_ROWID2");
    let last = rows(&b).pop().unwrap();
    assert_eq!(last[0], "10");
    assert_eq!(last[1], "<NULL>");
    assert_eq!(last[2], "*BAMAFbMCwQL+");
}

/// Rounds `truth` (a plain decimal text) half away from zero to `scale` fractional digits, from the text alone.
fn round_text(t: &str, scale: usize) -> String {
    let (neg, rest) = match t.strip_prefix('-') {
        Some(r) => (true, r),
        None => (false, t),
    };
    let (ip, fp) = rest.split_once('.').unwrap_or((rest, ""));
    let ip = if ip.is_empty() { "0" } else { ip };
    let mut digits: Vec<u8> = ip
        .bytes()
        .chain(fp.bytes().take(scale))
        .map(|c| c - b'0')
        .collect();
    digits.extend(std::iter::repeat_n(0, scale.saturating_sub(fp.len())));
    if fp.as_bytes().get(scale).is_some_and(|&c| c >= b'5') {
        let mut i = digits.len();
        loop {
            if i == 0 {
                digits.insert(0, 1);
                break;
            }
            i -= 1;
            if digits[i] == 9 {
                digits[i] = 0;
            } else {
                digits[i] += 1;
                break;
            }
        }
    }
    let s: String = digits.iter().map(|d| char::from(b'0' + d)).collect();
    decimal_text(&format!("{}{s}", if neg { "-" } else { "" }), scale)
}

/// The computed quotients of `truth_num3.txt` in a column declared `NUMBER` (Decimal128(38,10)): the owner's
/// default `round` rounds them half away from zero below the 10th decimal and counts them in one
/// `W-NUMBER-ROUNDED` (6 values, 0 became 0); `error` stops at row 1 with `E-NUMBER-OVERFLOW`; `null` writes
/// 6 NULLs and one `W-NUMBER-NULLED`; `number_types` `decimal256(76,38)` keeps 38 decimals (rounded from
/// the 40-digit truth). The expected texts are computed from the truth text by decimal string arithmetic.
#[test]
fn number_overflow_policies_on_t_num3() {
    let truth3: Vec<Vec<String>> = truth("18c", "truth_num3.txt");
    assert_eq!(truth3.len(), 6);
    let mut d = open_fixture("18c/t_num3_exp_18c.dmp");
    let (b, w) = read(&mut d, "T_NUM3", &opts());
    let want: Vec<String> = truth3.iter().map(|l| round_text(&l[1], 10)).collect();
    assert_eq!(col(&b, 1), want);
    let w: Vec<_> = w
        .iter()
        .filter(|w| w.code == WarningCode::NumberRounded)
        .collect();
    assert_eq!(w.len(), 1);
    assert_eq!(
        (w[0].count, w[0].count_to_zero, w[0].row, w[0].column),
        (Some(6), Some(0), Some(1), Some(2))
    );
    let f = b[0].schema().field(1).clone();
    assert_eq!(
        f.metadata()
            .get("oradmp:number_overflow")
            .map(String::as_str),
        Some("round")
    );

    let e = try_read(
        &mut d,
        "T_NUM3",
        &ReadOptions {
            on_number_overflow: OverflowPolicy::Error,
            ..opts()
        },
    )
    .unwrap_err();
    assert_eq!(e.code, ErrorCode::NumberOverflow);
    assert_eq!((e.row, e.column), (Some(1), Some(2)));

    let (b, w) = read(
        &mut d,
        "T_NUM3",
        &ReadOptions {
            on_number_overflow: OverflowPolicy::Null,
            ..opts()
        },
    );
    assert_eq!(col(&b, 1), vec!["<NULL>"; 6]);
    assert_eq!(
        w.iter()
            .filter(|w| w.code == WarningCode::NumberNulled && w.count == Some(6))
            .count(),
        1
    );

    // Decimal256 builder by a `number_types` override
    let mut o = Options::default();
    o.types.number_types.insert(
        "T_NUM3.V".to_string(),
        NumberType::Decimal256 {
            precision: 76,
            scale: 38,
        },
    );
    let mut d = open(root().join("corpus/fixtures/18c/t_num3_exp_18c.dmp"), o).unwrap();
    let (b, w) = read(&mut d, "T_NUM3", &opts());
    assert_eq!(
        b[0].schema().field(1).data_type(),
        &DataType::Decimal256(76, 38)
    );
    let want: Vec<String> = truth3.iter().map(|l| round_text(&l[1], 38)).collect();
    assert_eq!(col(&b, 1), want);
    let r: Vec<_> = w
        .iter()
        .filter(|w| w.code == WarningCode::NumberRounded)
        .collect();
    assert_eq!(r.len(), 1, "40-digit values lose digits 39 and 40");
}

/// `truth_date.txt`: rows 8 and 9 (years -100 and -4712) are `E-BAD-DATETIME` (ADR-28), at row 8, column 2,
/// part 1 with the offset; with `on_value_error="null"` they are NULL with one `W-VALUE-NULLED` (count 2), the
/// other rows equal the truth text (row 11 is NULL).
#[test]
fn dates_below_year_1_raise_or_become_null() {
    let mut d = open_fixture("18c/t_date_exp_18c.dmp");
    let e = try_read(&mut d, "T_DATE", &opts()).unwrap_err();
    assert_eq!(e.code, ErrorCode::BadDatetime);
    assert_eq!(
        (e.row, e.column, e.part, e.table),
        (Some(8), Some(2), Some(1), Some(1))
    );
    assert!(e.offset.is_some());
    let (b, w) = read(
        &mut d,
        "T_DATE",
        &ReadOptions {
            on_value_error: OnValueError::Null,
            ..opts()
        },
    );
    let r = rows(&b);
    for l in truth("18c", "truth_date.txt") {
        let i: usize = l[0].parse().unwrap();
        let got = &r[i - 1][1];
        match i {
            8 | 9 => assert_eq!(got, "<NULL>"),
            11 => assert_eq!(got, "<NULL>"),
            _ => assert_eq!(got, l[1].trim(), "row {i}"),
        }
    }
    let n: Vec<_> = w
        .iter()
        .filter(|w| w.code == WarningCode::ValueNulled)
        .collect();
    assert_eq!(n.len(), 1);
    assert_eq!(
        (n[0].count, n[0].row, n[0].column),
        (Some(2), Some(8), Some(2))
    );
}

/// `YYYY-MM-DD HH:MM:SS[.fff]` to (seconds since the epoch, nanoseconds).
fn parse_ts(t: &str) -> (i64, i64) {
    let (date, time) = t.split_once(' ').unwrap();
    let (hms, frac) = time.split_once('.').unwrap_or((time, ""));
    let d: Vec<i64> = date.split('-').map(|x| x.parse().unwrap()).collect();
    let h: Vec<i64> = hms.split(':').map(|x| x.parse().unwrap()).collect();
    let days = days_from_civil(d[0], d[1] as u32, d[2] as u32);
    let nanos = if frac.is_empty() {
        0
    } else {
        format!("{frac:0<9}").parse().unwrap()
    };
    (days * 86_400 + h[0] * 3600 + h[1] * 60 + h[2], nanos)
}

/// `truth_ts.txt`: TIMESTAMP(0) and (6) are Timestamp(Microsecond), (9) is Timestamp(Nanosecond); every value
/// equals the truth text converted by the test's own civil-date arithmetic. Row 5 (9999-12-31) is outside the
/// 64-bit nanosecond range: `E-BAD-DATETIME`, or NULL with `on_value_error="null"`.
/// `truth_tstz.txt`: the TSTZ instant is the local time minus its offset, labelled UTC; the zone is not
/// delivered; TSLTZ is delivered as stored.
#[test]
fn timestamps_equal_the_truth_in_the_declared_unit() {
    let mut d = open_fixture("18c/t_ts_exp_18c.dmp");
    let e = try_read(&mut d, "T_TS", &opts()).unwrap_err();
    assert_eq!(
        (e.code, e.row, e.column),
        (ErrorCode::BadDatetime, Some(5), Some(4))
    );
    let (b, w) = read(
        &mut d,
        "T_TS",
        &ReadOptions {
            on_value_error: OnValueError::Null,
            ..opts()
        },
    );
    let r = rows(&b);
    for l in truth("18c", "truth_ts.txt") {
        let i: usize = l[0].parse().unwrap();
        for (c, text, unit) in [(1usize, &l[1], 1_000i64), (2, &l[3], 1_000), (3, &l[5], 1)] {
            let got = &r[i - 1][c];
            if text == "<NULL>" || (i == 5 && c == 3) {
                assert_eq!(got, "<NULL>", "row {i} col {c}");
                continue;
            }
            let (secs, nanos) = parse_ts(text);
            let want = (i128::from(secs) * 1_000_000_000 + i128::from(nanos)) / i128::from(unit);
            assert_eq!(got, &want.to_string(), "row {i} col {c}");
        }
    }
    assert_eq!(
        w.iter()
            .filter(|w| w.code == WarningCode::ValueNulled)
            .count(),
        1
    );

    let mut d = open_fixture("18c/t_tstz_exp_18c.dmp");
    let (b, w) = read(&mut d, "T_TSTZ", &opts());
    assert!(w.is_empty(), "{w:?}");
    assert_eq!(
        b[0].schema().field(1).data_type(),
        &DataType::Timestamp(TimeUnit::Microsecond, Some("UTC".into()))
    );
    let r = rows(&b);
    for l in truth("18c", "truth_tstz.txt") {
        let i: usize = l[0].parse().unwrap();
        let row = r.iter().position(|x| x[0] == l[0]).unwrap();
        // "tstz=2016-03-26 19:34:55.123456 +05:30 +05:30"
        if let Some(t) = l[1].strip_prefix("tstz=").filter(|t| *t != "<NULL>") {
            let parts: Vec<&str> = t.split(' ').collect();
            let (secs, nanos) = parse_ts(&format!("{} {}", parts[0], parts[1]));
            let off = parts[2];
            let sign = if off.starts_with('-') { -1 } else { 1 };
            let (oh, om) = off[1..].split_once(':').unwrap();
            let offset =
                sign * (oh.parse::<i64>().unwrap() * 3600 + om.parse::<i64>().unwrap() * 60);
            let want = (secs - offset) * 1_000_000 + nanos / 1000;
            assert_eq!(r[row][1], want.to_string(), "TSTZ id {i}");
        } else {
            assert_eq!(r[row][1], "<NULL>", "TSTZ id {i}");
        }
        if let Some(t) = l[3].strip_prefix("tsltz=").filter(|t| *t != "<NULL>") {
            let (secs, nanos) = parse_ts(t);
            assert_eq!(
                r[row][2],
                (secs * 1_000_000 + nanos / 1000).to_string(),
                "TSLTZ id {i}"
            );
        } else {
            assert_eq!(r[row][2], "<NULL>");
        }
    }
}
